from __future__ import annotations

from pathlib import Path


def replace(path: str, old: str, new: str, count: int = 1) -> None:
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    if old not in text:
        raise SystemExit(f"missing M1 anchor in {path}: {old[:160]!r}")
    p.write_text(text.replace(old, new, count), encoding="utf-8")


def main() -> None:
    Path("app/models/publication_qualification.py").write_text('''"""Append-only, context-bound publication qualification assessments."""\n\nfrom __future__ import annotations\n\nimport datetime as dt\nimport enum\nimport uuid\n\nfrom sqlalchemy import JSON, DateTime, Enum, ForeignKey, String, Uuid\nfrom sqlalchemy.orm import Mapped, mapped_column\n\nfrom app.core.time import utc_now\nfrom app.models.base import Base, UUIDPkMixin, enum_values\n\n\nclass PublicationQualificationStatus(enum.StrEnum):\n    QUALIFIED = "qualified"\n    NOT_QUALIFIED = "not_qualified"\n    REVALIDATION_REQUIRED = "revalidation_required"\n\n\nclass PublicationQualificationAssessment(UUIDPkMixin, Base):\n    """Immutable assessment for one exact publication context."""\n\n    __tablename__ = "publication_qualification_assessment"\n\n    catalog_revision_id: Mapped[uuid.UUID] = mapped_column(\n        ForeignKey("catalog_revision.id"), nullable=False, index=True\n    )\n    channel: Mapped[str] = mapped_column(String(32), nullable=False)\n    purpose: Mapped[str] = mapped_column(String(64), nullable=False)\n    source_revision_refs: Mapped[list] = mapped_column(JSON, nullable=False, default=list)\n    source_fingerprint: Mapped[str] = mapped_column(String(64), nullable=False)\n    policy_version: Mapped[str] = mapped_column(String(64), nullable=False)\n    adapter_version: Mapped[str] = mapped_column(String(64), nullable=False)\n    environment_ref: Mapped[str] = mapped_column(String(128), nullable=False)\n    assessment_status: Mapped[PublicationQualificationStatus] = mapped_column(\n        Enum(\n            PublicationQualificationStatus,\n            native_enum=False,\n            length=32,\n            values_callable=enum_values,\n        ),\n        nullable=False,\n    )\n    evidence_refs: Mapped[list] = mapped_column(JSON, nullable=False, default=list)\n    assessed_at: Mapped[dt.datetime] = mapped_column(\n        DateTime(timezone=True), nullable=False, default=utc_now\n    )\n\n\n__all__ = [\n    "PublicationQualificationAssessment",\n    "PublicationQualificationStatus",\n]\n''', encoding="utf-8")

    Path("app/services/publication_qualification.py").write_text('''"""Current-use publication qualification without rewriting catalog lifecycle."""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nimport uuid\nfrom collections.abc import Iterable\n\nfrom sqlalchemy import select\n\nfrom app.core.errors import NotFoundError, ValidationError\nfrom app.models.catalog import CatalogRevision\nfrom app.models.publication_qualification import (\n    PublicationQualificationAssessment,\n    PublicationQualificationStatus,\n)\n\n\ndef catalog_revision_fingerprint(revision: CatalogRevision) -> str:\n    """Fingerprint publication-relevant source content, independent of lifecycle status."""\n    payload = {\n        "id": str(revision.id),\n        "sku": revision.sku,\n        "title": revision.title,\n        "description": revision.description,\n        "category": revision.category,\n        "current": revision.current,\n        "proposed": revision.proposed,\n    }\n    encoded = json.dumps(\n        payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False, default=str\n    ).encode("utf-8")\n    return hashlib.sha256(encoded).hexdigest()\n\n\ndef _required_text(value: str, field: str) -> str:\n    text = str(value or "").strip()\n    if not text:\n        raise ValidationError(f"{field} is required for publication qualification")\n    return text\n\n\ndef append_publication_qualification_assessment(\n    db,\n    *,\n    catalog_revision_id: uuid.UUID,\n    channel: str,\n    purpose: str,\n    policy_version: str,\n    adapter_version: str,\n    environment_ref: str,\n    assessment_status: PublicationQualificationStatus | str,\n    evidence_refs: Iterable[str] = (),\n    source_revision_refs: Iterable[str] = (),\n) -> PublicationQualificationAssessment:\n    """Append one assessment. No existing assessment is updated or backfilled."""\n    revision = db.get(CatalogRevision, catalog_revision_id)\n    if revision is None:\n        raise NotFoundError("catalog revision not found")\n    status = PublicationQualificationStatus(assessment_status)\n    evidence = [str(ref).strip() for ref in evidence_refs if str(ref).strip()]\n    if status is PublicationQualificationStatus.QUALIFIED and not evidence:\n        raise ValidationError("qualified publication assessment requires evidence_refs")\n    refs = [str(ref).strip() for ref in source_revision_refs if str(ref).strip()]\n    if not refs:\n        refs = [f"catalog_revision:{revision.id}"]\n    assessment = PublicationQualificationAssessment(\n        catalog_revision_id=revision.id,\n        channel=_required_text(channel, "channel"),\n        purpose=_required_text(purpose, "purpose"),\n        source_revision_refs=refs,\n        source_fingerprint=catalog_revision_fingerprint(revision),\n        policy_version=_required_text(policy_version, "policy_version"),\n        adapter_version=_required_text(adapter_version, "adapter_version"),\n        environment_ref=_required_text(environment_ref, "environment_ref"),\n        assessment_status=status,\n        evidence_refs=evidence,\n    )\n    db.add(assessment)\n    db.flush()\n    return assessment\n\n\ndef latest_applicable_assessment(\n    db,\n    *,\n    revision: CatalogRevision,\n    channel: str,\n    purpose: str,\n    policy_version: str,\n    adapter_version: str,\n    environment_ref: str,\n) -> PublicationQualificationAssessment | None:\n    """Latest assessment bound to the exact current source and publication context."""\n    return (\n        db.execute(\n            select(PublicationQualificationAssessment)\n            .where(\n                PublicationQualificationAssessment.catalog_revision_id == revision.id,\n                PublicationQualificationAssessment.channel == channel,\n                PublicationQualificationAssessment.purpose == purpose,\n                PublicationQualificationAssessment.source_fingerprint\n                == catalog_revision_fingerprint(revision),\n                PublicationQualificationAssessment.policy_version == policy_version,\n                PublicationQualificationAssessment.adapter_version == adapter_version,\n                PublicationQualificationAssessment.environment_ref == environment_ref,\n            )\n            .order_by(\n                PublicationQualificationAssessment.assessed_at.desc(),\n                PublicationQualificationAssessment.id.desc(),\n            )\n            .limit(1)\n        )\n        .scalars()\n        .first()\n    )\n\n\ndef require_current_publication_qualification(\n    db,\n    *,\n    catalog_revision_id: uuid.UUID,\n    expected_sku: str,\n    channel: str,\n    purpose: str,\n    policy_version: str,\n    adapter_version: str,\n    environment_ref: str,\n) -> PublicationQualificationAssessment:\n    """Fail closed unless the latest exact-context assessment is QUALIFIED."""\n    revision = db.get(CatalogRevision, catalog_revision_id)\n    if revision is None:\n        raise ValidationError("publication requires a known catalog revision")\n    if revision.sku != expected_sku:\n        raise ValidationError("publication qualification revision does not match listing SKU")\n    assessment = latest_applicable_assessment(\n        db,\n        revision=revision,\n        channel=_required_text(channel, "channel"),\n        purpose=_required_text(purpose, "purpose"),\n        policy_version=_required_text(policy_version, "policy_version"),\n        adapter_version=_required_text(adapter_version, "adapter_version"),\n        environment_ref=_required_text(environment_ref, "environment_ref"),\n    )\n    if assessment is None:\n        raise ValidationError("current publication qualification assessment is required")\n    if assessment.assessment_status is not PublicationQualificationStatus.QUALIFIED:\n        raise ValidationError(\n            "latest publication qualification assessment is not qualified: "\n            f"{assessment.assessment_status.value}"\n        )\n    return assessment\n\n\n__all__ = [\n    "append_publication_qualification_assessment",\n    "catalog_revision_fingerprint",\n    "latest_applicable_assessment",\n    "require_current_publication_qualification",\n]\n''', encoding="utf-8")

    Path("app/api/v1/publication_qualifications.py").write_text('''"""Append-only publication qualification assessment API."""\n\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import Annotated\n\nfrom fastapi import APIRouter, Depends\nfrom pydantic import BaseModel, Field\nfrom sqlalchemy.orm import Session\n\nfrom app.api.deps import get_current_user, get_session, require_roles\nfrom app.models.publication_qualification import PublicationQualificationStatus\nfrom app.services.publication_qualification import append_publication_qualification_assessment\n\nrouter = APIRouter(prefix="/v1", tags=["publication-qualification"])\n\n\nclass PublicationQualificationAssessmentCreate(BaseModel):\n    catalog_revision_id: uuid.UUID\n    channel: str = Field(min_length=1, max_length=32)\n    purpose: str = Field(default="publish", min_length=1, max_length=64)\n    policy_version: str = Field(min_length=1, max_length=64)\n    adapter_version: str = Field(min_length=1, max_length=64)\n    environment_ref: str = Field(min_length=1, max_length=128)\n    assessment_status: PublicationQualificationStatus\n    evidence_refs: list[str] = Field(default_factory=list)\n    source_revision_refs: list[str] = Field(default_factory=list)\n\n\n@router.post("/publication-qualifications")\ndef create_assessment(\n    body: PublicationQualificationAssessmentCreate,\n    db: Annotated[Session, Depends(get_session)],\n    _user_id: Annotated[uuid.UUID, Depends(get_current_user)],\n    _authorized: Annotated[bool, Depends(require_roles("catalog_owner"))],\n) -> dict[str, object]:\n    assessment = append_publication_qualification_assessment(\n        db,\n        catalog_revision_id=body.catalog_revision_id,\n        channel=body.channel,\n        purpose=body.purpose,\n        policy_version=body.policy_version,\n        adapter_version=body.adapter_version,\n        environment_ref=body.environment_ref,\n        assessment_status=body.assessment_status,\n        evidence_refs=body.evidence_refs,\n        source_revision_refs=body.source_revision_refs,\n    )\n    return {\n        "assessmentId": str(assessment.id),\n        "catalogRevisionId": str(assessment.catalog_revision_id),\n        "assessmentStatus": assessment.assessment_status.value,\n        "sourceFingerprint": assessment.source_fingerprint,\n        "assessedAt": assessment.assessed_at.isoformat(),\n    }\n''', encoding="utf-8")

    Path("alembic/versions/0007_publication_qualification.py").write_text('''"""append-only publication qualification assessments\n\nRevision ID: 0007_publication_qualification\nRevises: 0006_remote_entity_ids\nCreate Date: 2026-08-24\n\nHistorical catalog revisions are not backfilled: OFFICIAL does not imply a\ncurrent publication qualification assessment.\n"""\n\nfrom __future__ import annotations\n\nimport sqlalchemy as sa\n\nfrom alembic import op\n\nrevision = "0007_publication_qualification"\ndown_revision = "0006_remote_entity_ids"\nbranch_labels = None\ndepends_on = None\n\n\ndef upgrade() -> None:\n    op.create_table(\n        "publication_qualification_assessment",\n        sa.Column("catalog_revision_id", sa.Uuid(), nullable=False),\n        sa.Column("channel", sa.String(length=32), nullable=False),\n        sa.Column("purpose", sa.String(length=64), nullable=False),\n        sa.Column("source_revision_refs", sa.JSON(), nullable=False),\n        sa.Column("source_fingerprint", sa.String(length=64), nullable=False),\n        sa.Column("policy_version", sa.String(length=64), nullable=False),\n        sa.Column("adapter_version", sa.String(length=64), nullable=False),\n        sa.Column("environment_ref", sa.String(length=128), nullable=False),\n        sa.Column("assessment_status", sa.String(length=32), nullable=False),\n        sa.Column("evidence_refs", sa.JSON(), nullable=False),\n        sa.Column("assessed_at", sa.DateTime(timezone=True), nullable=False),\n        sa.Column("id", sa.Uuid(), nullable=False),\n        sa.ForeignKeyConstraint(\n            ["catalog_revision_id"],\n            ["catalog_revision.id"],\n            name="fk_publication_qualification_assessment_catalog_revision_id_catalog_revision",\n        ),\n        sa.PrimaryKeyConstraint("id", name="pk_publication_qualification_assessment"),\n    )\n    op.create_index(\n        "ix_publication_qualification_assessment_catalog_revision_id",\n        "publication_qualification_assessment",\n        ["catalog_revision_id"],\n        unique=False,\n    )\n\n\ndef downgrade() -> None:\n    op.drop_index(\n        "ix_publication_qualification_assessment_catalog_revision_id",\n        table_name="publication_qualification_assessment",\n    )\n    op.drop_table("publication_qualification_assessment")\n''', encoding="utf-8")

